+        <div class="section-header">
+          <h2>Research Log</h2>
+          <span class="count" id="research-count">0</span>
+        </div>
+        <div class="section-body">
+          <div id="research-log-body"></div>
+        </div>
+      </div>
+
     </div>
   </main>

@@ -558,6 +605,35 @@ function parseDecisions(raw) {
   });
 }

+function parseResearchLog(stateMd) {
+  if (!stateMd) return [];
+  const lines = stateMd.split('\n');
+  let inside = false;
+  const sectionLines = [];
+  for (const line of lines) {
+    if (!inside && /^## Research Log/.test(line)) { inside = true; continue; }
+    if (inside) {
+      if (/^## /.test(line)) break;
+      sectionLines.push(line);
+    }
+  }
+  if (!sectionLines.length) return [];
+
+  const entries = [];
+  let current = null;
+  for (const line of sectionLines) {
+    if (/^### /.test(line)) {
+      if (current) entries.push(current);
+      current = { title: line.replace(/^### /, '').trim(), bodyLines: [] };
+    } else if (current) {
+      current.bodyLines.push(line);
+    }
+  }
+  if (current) entries.push(current);
+
+  return entries.map(e => ({ title: e.title, body: e.bodyLines.join('\n').trim() }));
+}
+
 // ── Rendering ─────────────────────────────────────────────────────────────

 const COLUMNS = ['planned', 'active', 'review', 'done'];
@@ -708,6 +784,42 @@ function renderMandate(stateRaw) {
   $('mandate-body').innerHTML = marked.parse(md);
 }

+function renderResearchLog(entries) {
+  $('research-count').textContent = entries.length;
+  const container = $('research-log-body');
+  container.innerHTML = '';
+
+  if (!entries.length) {
+    container.innerHTML = '<span style="color:var(--muted);font-size:12px">No research log entries yet.</span>';
+    return;
+  }
+
+  entries.forEach(entry => {
+    const card = document.createElement('div');
+    card.className = 'research-card';
+
+    const header = document.createElement('div');
+    header.className = 'research-card-header';
+    header.innerHTML = `
+      <span class="research-card-title">${escHtml(entry.title)}</span>
+      <span class="research-card-toggle">▶</span>
+    `;
+
+    const body = document.createElement('div');
+    body.className = 'research-card-body';
+    body.innerHTML = marked.parse(entry.body);
+
+    header.addEventListener('click', () => {
+      const open = body.classList.toggle('open');
+      header.querySelector('.research-card-toggle').textContent = open ? '▼' : '▶';
+    });
+
+    card.appendChild(header);
+    card.appendChild(body);
+    container.appendChild(card);
+  });
+}
+
 // ── Utilities ─────────────────────────────────────────────────────────────

 function escHtml(str) {
@@ -758,6 +870,7 @@ async function loadDashboard() {
     renderTaskBoard(data.taskData);
     renderDecisions(parseDecisions(data.decisionsRaw));
     renderCycles(data.runs);
+    renderResearchLog(parseResearchLog(data.stateRaw));

     $('header-repo').textContent = repo;
     $('site-header').style.display   = 'flex';

